from azure.mgmt.cdn.models import (ProtectionPolicy, ProtectedItem, ProtectionContainer, ProtectableItem)
from azure.cli.core.util import CLIError

def disable_protection(cmd, client, resource_group_name, vault_name, item_name, container_name,
                       backup_management_type=None, workload_type=None, delete_backup_data=False, **kwargs):

    items_client = client.protected_items
    item = show_item(cmd, items_client, resource_group_name, vault_name, container_name, item_name,
                     backup_management_type, workload_type)

    if not item:
        raise CLIError("Item not found")

    if isinstance(item, list):
        raise CLIError("Multiple items found. Please give native names instead.")

    if item.properties.backup_management_type.lower() == "azureiaasvm":
        return client.protection_policies.disable_protection(resource_group_name, vault_name, item.id, delete_backup_data)
    if item.properties.backup_management_type.lower() == "azurestorage":
        return client.protection_containers.disable_protection(resource_group_name, vault_name, container_name, item_name, delete_backup_data)
    if item.properties.backup_management_type.lower() == "azureworkload":
        return client.protectable_items.disable_protection(resource_group_name, vault_name, container_name, item_name, delete_backup_data)
    return None
