            data = OrderedDict([('status', 'error'), ('message', message), ('data', exc.detail)])
        else:
            data = OrderedDict([('status', 'error'), ('message', exc.detail)])

        set_rollback()
        return Response(data, status=exc.status_code, headers=headers)

    elif isinstance(exc, Http404):
        msg = _('Not found.')
