import tensorflow as tf
from tensorflow.keras.initializers import GlorotUniform, Ones

class MLGWalk () :
    def dense(self, inputs, output_dim, name, is_private=True):
        '''
            Dense layer

            inputs -- input vectors
            output_dim -- output dimension 
            name -- name of the operation
            is_private -- independent weights per label agent
        '''
        shape = inputs.get_shape().as_list()
        if len(shape) > 4:
            if is_private:
                W = tf.Variable(name='W_{}'.format(name),
                               initial_value=GlorotUniform()((shape[0], shape[-1], output_dim)))
                b = tf.Variable(name='b_{}'.format(name), initial_value=-1*Ones()(output_dim))

                return tf.nn.bias_add(tf.einsum('abilj,ajk->abilk', inputs, W), b)
            else:
                W = tf.Variable(name='W_{}'.format(name),
                               initial_value=GlorotUniform()((shape[-1], output_dim)))
                b = tf.Variable(name='b_{}'.format(name), initial_value=-1*Ones()(output_dim))

                return tf.nn.bias_add(tf.einsum('abilj,jk->abilk', inputs, W), b)

        else:
            W = tf.Variable(name='W_{}'.format(name),
                           initial_value=GlorotUniform()((shape[0], shape[-1], output_dim)))
            b = tf.Variable(name='b_{}'.format(name), initial_value=-1*Ones()(output_dim))

            return tf.nn.bias_add(tf.einsum('abij,ajk->abik', inputs, W), b)
